select count(*)::int as n from (values ('appointment_email_private', 'advance_intake_epoch'), ('appointment_email_private', 'lock_authority_scope'), ('appointment_email_private', 'read_authority'), ('appointment_email_private', 'revise_authority'), ('appointment_email_private', 'snapshot_authority'), ('public', 'advance_intake_revision'), ('public', 'authorize_appointment_email_operation'), ('public', 'claim_session_payment_charge_attempt'), ('public', 'inspect_appointment_email_operation'), ('public', 'observe_appointment_email_operation'), ('public', 'prepare_appointment_email_operation'), ('public', 'record_email_attempt'), ('public', 'retire_unattempted_appointment_email_operation')) v(s, f) where exists (select 1 from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid = p.pronamespace where n.nspname = v.s and p.proname = v.f)
